#!/bin/bash
set -Eeuo pipefail

HOSTS_FILE=${1:-/opt/scripts/hosts.txt}
SSH_USER=${SSH_USER:-ops}
CONCURRENCY=${CONCURRENCY:-5}
CMD=${2:-uptime}
OUTDIR=/var/log/batch-$(date +%F_%H%M%S)

[ -f "$HOSTS_FILE" ] || { echo "主机清单不存在: $HOSTS_FILE" >&2; exit 1; }
mkdir -p "$OUTDIR"

run_one() {
  local host=$1
  if timeout 15 ssh -n -p 22 -o BatchMode=yes -o ConnectTimeout=5 "$SSH_USER@$host" "$CMD" > "$OUTDIR/$host.out" 2>&1; then
    echo "[OK]   $host"
  else
    echo "[FAIL] $host"
  fi
}
export -f run_one
export SSH_USER OUTDIR CMD

grep -vE '^[[:space:]]*(#|$)' "$HOSTS_FILE" | xargs -P "$CONCURRENCY" -I{} bash -c 'run_one "$@"' _ {}

echo "全部完成，逐台结果见: $OUTDIR"
ls -1 "$OUTDIR" | wc -l
